import { useId, useLayoutEffect, useRef, useState } from 'react';
import './TokenSearch.css';
export interface FilterToken { id: string; label: string }
export interface SearchValue { text: string; tokens: readonly FilterToken[] }
export interface Suggestion { id: string; label: string }
export type SearchAction =
  | { type: 'text'; text: string; caret: number }
  | { type: 'remove-token'; id: string }
  | { type: 'edit-token'; id: string }
  | { type: 'choose-suggestion'; id: string; replacingTokenId: string | null; caret: number }
  | { type: 'clear' }
  | { type: 'submit' };
export function TokenSearch({ value, suggestions, replacingTokenId, dispatch, restoreCaret }: {
  value: SearchValue; suggestions: readonly Suggestion[]; replacingTokenId: string | null;
  dispatch: (action: SearchAction) => void; restoreCaret?: { revision: number; offset: number };
}) {
  const id = useId();
  const input = useRef<HTMLInputElement>(null);
  const [active, setActive] = useState<string | null>(null);
  const [focused, setFocused] = useState(false);
  const [announcement, setAnnouncement] = useState('');
  const activeIndex = suggestions.findIndex(item => item.id === active);
  const expanded = focused && suggestions.length > 0;
  useLayoutEffect(() => { if (restoreCaret) { input.current?.focus(); const offset = Math.min(value.text.length, Math.max(0, restoreCaret.offset)); input.current?.setSelectionRange(offset, offset); } }, [restoreCaret?.revision]);
  function choose(suggestion: Suggestion) {
    dispatch({ type: 'choose-suggestion', id: suggestion.id, replacingTokenId, caret: input.current?.selectionStart ?? value.text.length });
    setActive(null);
    setAnnouncement((replacingTokenId ? 'Replaced filter with ' : 'Added filter ') + suggestion.label);
    input.current?.focus();
  }
  function remove(token: FilterToken) { dispatch({ type: 'remove-token', id: token.id }); setAnnouncement('Removed filter ' + token.label); input.current?.focus(); }
  return <div className="token-search" role="search" aria-label="Workspace search">
    <label htmlFor={id}>Search workspace</label>
    <div className="search-editor">{value.tokens.map(token => <span className="filter-token" key={token.id}>
      <button type="button" aria-label={'Edit filter ' + token.label} onClick={() => { dispatch({ type: 'edit-token', id: token.id }); input.current?.focus(); }}>{token.label}</button>
      <button type="button" aria-label={'Remove filter ' + token.label} onClick={() => remove(token)}>×</button>
    </span>)}
    <input ref={input} id={id} type="text" role="combobox" aria-autocomplete="list" aria-expanded={expanded} aria-controls={expanded ? id + '-suggestions' : undefined} aria-activedescendant={expanded && activeIndex >= 0 ? id + '-option-' + activeIndex : undefined} aria-describedby={id + '-help'} value={value.text}
      onFocus={() => setFocused(true)} onBlur={() => { setFocused(false); setActive(null); }}
      onChange={event => { dispatch({ type: 'text', text: event.target.value, caret: event.target.selectionStart ?? event.target.value.length }); setActive(null); }}
      onKeyDown={event => {
        if (event.nativeEvent.isComposing) return;
        if ((event.key === 'ArrowDown' || event.key === 'ArrowUp') && suggestions.length) { event.preventDefault(); const step = event.key === 'ArrowDown' ? 1 : -1; const index = activeIndex < 0 ? (step > 0 ? 0 : suggestions.length - 1) : (activeIndex + step + suggestions.length) % suggestions.length; setActive(suggestions[index].id); }
        else if (event.key === 'Enter') { event.preventDefault(); if (expanded && activeIndex >= 0) choose(suggestions[activeIndex]); else dispatch({ type: 'submit' }); }
        else if (event.key === 'Escape') { setFocused(false); setActive(null); }
        else if (event.key === 'Backspace' && !value.text && value.tokens.length) { event.preventDefault(); remove(value.tokens[value.tokens.length - 1]); }
      }}/>
    <button type="button" disabled={!value.text && !value.tokens.length} onClick={() => { dispatch({ type: 'clear' }); setAnnouncement('Search cleared'); setActive(null); input.current?.focus(); }}>Clear search</button></div>
    <p id={id + '-help'}>Use arrow keys for suggestions and Enter to choose. Tab to edit or remove filters. Backspace in an empty search removes the last filter.</p>
    {expanded && <ul id={id + '-suggestions'} role="listbox" aria-label="Search suggestions">{suggestions.map((suggestion, index) => <li key={suggestion.id} id={id + '-option-' + index} role="option" aria-selected={active === suggestion.id} onMouseDown={event => event.preventDefault()} onClick={() => choose(suggestion)}>{suggestion.label}</li>)}</ul>}
    <span role="status" className="search-announcement">{announcement}</span>
  </div>;
}

