.token-search { max-width: 48rem; }
.search-editor { display: flex; flex-wrap: wrap; align-items: center; gap: .4rem; padding: .5rem; border: 1px solid #8b929e; border-radius: .4rem; }
.search-editor input { flex: 1 1 12rem; min-width: 3rem; width: 100%; padding: .45rem; }
.search-editor button, .search-editor input { font: inherit; }
.filter-token { display: inline-flex; max-width: 100%; background: #e7ecf5; border: 1px solid #b4c0d4; border-radius: .3rem; }
.filter-token button { border: 0; background: transparent; padding: .35rem; overflow-wrap: anywhere; }
.token-search :focus-visible { outline: 3px solid #205ed8; outline-offset: 2px; }
.token-search ul { margin: .25rem 0; padding: .25rem; list-style: none; border: 1px solid #8b929e; }
.token-search [role="option"] { padding: .5rem; cursor: pointer; }
.token-search [aria-selected="true"] { background: #dce7fa; outline: 1px solid #4567a2; }
.search-announcement { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
